package br.com.sussmartcare.notification.infrastructure; import br.com.sussmartcare.notification.application.NotificationChannel; import br.com.sussmartcare.notification.domain.Notification; import org.slf4j.*; import org.springframework.stereotype.Component; @Component public class StaffConsoleNotificationChannel implements NotificationChannel {private static final Logger log=LoggerFactory.getLogger(StaffConsoleNotificationChannel.class);public boolean supports(String c){return "STAFF_CONSOLE".equalsIgnoreCase(c);}public void send(Notification n){log.info("notification_delivered_simulated adapter=STAFF_CONSOLE patient={} visit={} type={}",n.getPatientId(),n.getVisitId(),n.getType());}}
